    static long[] factorial;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long pk = sc.nextLong();

        if (pk > N - 1) {
            System.out.println(0);
        } else {
            int k = (int) pk;
            factorial = new long[N + 1];
